# templatetags/pricing.py     (the app must be in INSTALLED_APPS)
from django import template
from django.utils.html import format_html

register = template.Library()

@register.simple_tag
def money(cents: int, currency: str = "EUR") -> str:
    return format_html('<span class="money">{:.2f} {}</span>',
                       cents / 100, currency)

# Jinja2: env.filters["money"] = lambda cents, cur="EUR": f"{cents / 100:.2f} {cur}"
